import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"认识数据中心","description":"从工程进入数据中心，找到数据点、接入源、工业采集、历史存储、计算和报警的入口。","frontmatter":{"title":"认识数据中心","description":"从工程进入数据中心，找到数据点、接入源、工业采集、历史存储、计算和报警的入口。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/datacenter.md","filePath":"zh/使用指南/认识数据中心.md"}'),i={name:"zh/guide/datacenter.md"};function o(l,t,n,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="认识数据中心" tabindex="-1">认识数据中心 <a class="header-anchor" href="#认识数据中心" aria-label="Permalink to &quot;认识数据中心&quot;">​</a></h1><p>数据中心用于配置<strong>当前工程</strong>的数据和业务逻辑。第一次使用时，先认清入口，再选择自己的任务，不必一次填完所有模块。</p><p>开始前，使用有该工程权限的组织账号登录。涉及现场设备、数据库或其他系统时，应先取得负责人的授权和连接资料；没有资料也可以先查看工程已有配置。</p><h2 id="_1-打开正确的工程" tabindex="-1">1. 打开正确的工程 <a class="header-anchor" href="#_1-打开正确的工程" aria-label="Permalink to &quot;1. 打开正确的工程&quot;">​</a></h2><ol><li>从公共入口登录组织，进入 <strong>“工程管理”</strong>。</li><li>找到目标工程，打开 <strong>“数据中心”</strong>。</li><li>核对当前工程，再通过左侧导航选择模块。</li></ol><p>数据中心与“应用开发”是不同入口：前者配置数据，后者维护页面源码与开发预览。不要只凭页面相似就认定正在操作同一个工程。</p><p>左侧入口以图标显示，鼠标停留或用键盘聚焦时会显示名称。首次加载请等待；读取失败时先重试，不把空白列表当成配置已丢失。</p><h2 id="_2-根据任务选择模块" tabindex="-1">2. 根据任务选择模块 <a class="header-anchor" href="#_2-根据任务选择模块" aria-label="Permalink to &quot;2. 根据任务选择模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>什么时候使用</th></tr></thead><tbody><tr><td>数据点</td><td>查找已生成的数据点，查看来源、详情和标签</td></tr><tr><td>接入源</td><td>配置数据库、消息和接口类连接，以及相应的数据来源</td></tr><tr><td>工业采集</td><td>配置工业协议连接、变量及节点上的调试与部署位置</td></tr><tr><td>历史存储</td><td>设置来源或数据点的历史保存方式</td></tr><tr><td>计算单元</td><td>维护计算脚本、触发配置和输出</td></tr><tr><td>报警单元</td><td>维护报警配置，并检查关联数据点与条件</td></tr></tbody></table><p>“接入源”和“工业采集”不是同一个连接列表。数据库或消息连接从接入源开始，PLC 等工业协议连接从工业采集开始；以本次交付提供的类型为准。</p><h2 id="_3-第一次配置按什么顺序" tabindex="-1">3. 第一次配置按什么顺序 <a class="header-anchor" href="#_3-第一次配置按什么顺序" aria-label="Permalink to &quot;3. 第一次配置按什么顺序&quot;">​</a></h2><ol><li><strong>先确认数据从哪里来</strong>：使用已有来源，或准备新的连接资料。</li><li><strong>再准备数据点</strong>：在对应来源中完成查询、变量或输出配置。数据点列表不是一个可以随意新建所有类型点位的空表。</li><li><strong>核对结果</strong>：查看数据点的路径、来源、类型及开发态当前值；有默认值不代表现场设备已经连通。</li><li><strong>按需要增加功能</strong>：分别设置历史保存、计算与报警，不把保存一份配置当成这些功能全部已启用。</li><li><strong>最后安排正式运行</strong>：核对版本、运行环境和部署条件；开发预览不能代替正式运行验证。</li></ol><p>刚开始可先<a href="/induframe-docs/zh/guide/datapoints.html">查看和整理数据点</a>。需要接入工业设备时，继续<a href="/induframe-docs/zh/guide/industrial-connections.html">配置工业采集连接</a>。</p><h2 id="_4-保存后怎样确认" tabindex="-1">4. 保存后怎样确认 <a class="header-anchor" href="#_4-保存后怎样确认" aria-label="Permalink to &quot;4. 保存后怎样确认&quot;">​</a></h2><ul><li>等待明确成功提示，再刷新或重新打开同一对象。</li><li>核对名称、所属工程、来源和保存后的字段。</li><li>涉及连接测试时，单独查看测试结果；“保存成功”与“连接成功”分别判断。</li><li>涉及运行数据时，同时核对质量、时间和来源，而不只看一个数值。</li></ul><p>出现错误时保留工程名称、模块、操作时间及提示，联系维护人员。不要提交完整密码、数据库连接密钥或设备凭据。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>需要维护页面时返回<a href="/induframe-docs/zh/guide/workspace.html">应用开发工作区</a>。准备正式使用前，先理解<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p>',18)])])}const u=a(i,[["render",o]]);export{p as __pageData,u as default};
